"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[1397],{4750(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>d,default:()=>u,frontMatter:()=>c,metadata:()=>a,toc:()=>h});const a=JSON.parse('{"id":"part2-backend-platform-security/oidc-oauth2-pkce-fastapi","title":"OIDC + OAuth2 + PKCE \u2192 Bearer Token \u2192 FastAPI Identity","description":"This is the same story end-to-end: how a React SPA securely obtains an access_token (PKCE), and how FastAPI validates that token and maps it to tenant_id + user_id per request.","source":"@site/docs/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi","permalink":"/tutorials/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":7,"frontMatter":{"title":"OIDC + OAuth2 + PKCE \u2192 Bearer Token \u2192 FastAPI Identity","slug":"/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi","description":"This is the same story end-to-end: how a React SPA securely obtains an access_token (PKCE), and how FastAPI validates that token and maps it to tenant_id + user_id per request.","sidebar_label":"8. OIDC, OAuth 2.0, and PKCE in FastAPI","pagination_label":"8. OIDC, OAuth 2.0, and PKCE in FastAPI","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"7. SSO, OAuth 2.0, and OIDC primer","permalink":"/tutorials/part2-backend-platform-security/06-sso-oauth2-oidc-primer"},"next":{"title":"9. First login and user provisioning","permalink":"/tutorials/part2-backend-platform-security/08-registering-new-users"}}');var i=n(4848),o=n(8453),s=n(8172);const r=JSON.parse('{"sourcePath":"part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi.html","route":"/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"OIDC + OAuth2 + PKCE \u2192 Bearer Token \u2192 FastAPI Identity","title":"OIDC + OAuth2 + PKCE \u2192 Bearer Token \u2192 FastAPI Identity","description":"This is the same story end-to-end: how a React SPA securely obtains an access_token (PKCE), and how FastAPI validates that token and maps it to tenant_id + user_id per request.","readingMinutes":8,"bodyClass":"","normalizeMath":false,"toc":[{"id":"bearer","label":"Bearer token per request (how FastAPI identifies callers)"},{"id":"oidc-vs-oauth2","label":"OAuth2 vs OIDC (in this story)"},{"id":"pkce","label":"What PKCE is (and why you need it)"},{"id":"setup","label":"What you must set up first (one-time)"},{"id":"sequence","label":"Concrete message sequence (OIDC Authorization Code + PKCE)"},{"id":"the-api-call-to-fastapi-per-user-per-request","label":"The API call to FastAPI (per user, per request)"},{"id":"backend-validation","label":"How the backend knows the token is \u201ccorrect\u201d"},{"id":"onboarding","label":"From a Verified Identity to Application Access"},{"id":"final-mapping","label":"How the Backend Maps a Dynamic Token to a Stable User ID"},{"id":"scale","label":"Why the Pattern Scales"}],"html":"<div class=\\"container\\">\\n    \\n    <p class=\\"lead\\">\\n      This is the same story end-to-end: how a React SPA securely obtains an <code>access_token</code> (PKCE),\\n      and how FastAPI validates that token and maps it to <code>tenant_id</code> + <code>user_id</code> per request.\\n    </p>\\n\\n    <div class=\\"card\\" id=\\"acronyms\\">\\n      <h3 id=\\"acronyms-quick-reference\\">Acronyms (quick reference)</h3>\\n      <ul>\\n        <li><strong>IdP</strong>: Identity Provider (e.g., Google Identity, Auth0, Okta, Entra ID)</li>\\n        <li><strong>OAuth2</strong>: OAuth 2.0 (authorization framework; how clients get tokens to call APIs)</li>\\n        <li><strong>OIDC</strong>: OpenID Connect (authentication layer on top of OAuth2; adds login + identity claims)</li>\\n        <li><strong>PKCE</strong>: Proof Key for Code Exchange (protects authorization-code flow for public clients like SPAs)</li>\\n        <li><strong>JWT</strong>: JSON Web Token (self-contained, signed token format commonly used for access tokens)</li>\\n        <li><strong>JWKS</strong>: JSON Web Key Set (IdP endpoint that publishes public signing keys for JWT verification)</li>\\n        <li><strong>SPA</strong>: Single Page Application (React running in the browser)</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"card\\" id=\\"jwt-jwks\\">\\n      <h3 id=\\"jwt-and-jwks-the-missing-piece\\">JWT &amp; JWKS (the missing piece)</h3>\\n      <p>\\n        The confusion usually comes from not separating two steps:\\n        <strong>(1) token issuance</strong> (frontend \u2194 IdP) vs <strong>(2) token validation</strong> (backend verifying the token).\\n      </p>\\n\\n      <h3 id=\\"jwt-json-web-token\\">JWT (JSON Web Token)</h3>\\n      <ul>\\n        <li>\\n          A <strong>JWT</strong> is a compact token format commonly used for <code>access_token</code>.\\n          It is typically <strong>signed</strong> so APIs can verify it hasn\u2019t been tampered with.\\n        </li>\\n        <li>\\n          It usually contains <strong>claims</strong> (e.g., <code>sub</code>, <code>iss</code>, <code>aud</code>, <code>exp</code>) inside the token payload.\\n        </li>\\n      </ul>\\n      <pre>JWT structure (conceptual):\\nheader.payload.signature\\n\\n- header: metadata (often includes \\"kid\\" = key id)\\n- payload: claims (sub, iss, aud, exp, ...)\\n- signature: proves the IdP signed it with its private key</pre>\\n\\n      <h3 id=\\"jwks-json-web-key-set\\">JWKS (JSON Web Key Set)</h3>\\n      <ul>\\n        <li>\\n          A <strong>JWKS</strong> is the IdP\u2019s published set of <strong>public keys</strong>.\\n          Your backend uses these public keys to verify the JWT signature.\\n        </li>\\n        <li>\\n          The backend typically fetches JWKS from a well-known IdP URL, caches it, and refreshes periodically (key rotation).\\n        </li>\\n        <li>\\n          The JWT header often includes <code>kid</code> so the backend can pick the correct public key from the JWKS.\\n        </li>\\n      </ul>\\n\\n      <div class=\\"callout\\">\\n        <strong>Where they come into the picture:</strong><br>\\n        The IdP issues an <code>access_token</code> (often a <strong>JWT</strong>). Then the backend validates the token signature using the IdP\u2019s <strong>JWKS</strong>.\\n        This is why the backend usually does <em>not</em> need to call the IdP \u201cto ask who the user is\u201d on every request.\\n      </div>\\n    </div>\\n\\n    <ul class=\\"toc\\">\\n      <li><a href=\\"#bearer\\">Bearer token per request</a></li>\\n      <li><a href=\\"#oidc-vs-oauth2\\">OAuth2 vs OIDC</a></li>\\n      <li><a href=\\"#pkce\\">What PKCE is</a></li>\\n      <li><a href=\\"#setup\\">One-time setup</a></li>\\n      <li><a href=\\"#sequence\\">Message sequence</a></li>\\n      <li><a href=\\"#backend-validation\\">Backend validation</a></li>\\n      <li><a href=\\"#jwks-fetch-cache\\">JWKS fetch/cache</a></li>\\n      <li><a href=\\"#onboarding\\">User registration &amp; access</a></li>\\n      <li><a href=\\"#final-mapping\\">Mapping Token to Identity</a></li>\\n      <li><a href=\\"#scale\\">Why it scales</a></li>\\n    </ul>\\n\\n    <h2 id=\\"bearer\\">Bearer token per request (how FastAPI identifies callers)</h2>\\n    <p>Your backend identifies the user (and tenant) because every request carries:</p>\\n    <pre>Authorization: Bearer &lt;token&gt;</pre>\\n    <p>The key questions are:</p>\\n    <ul>\\n      <li>How does the frontend generate <code>&lt;token&gt;</code> securely?</li>\\n      <li>How does the backend trust it?</li>\\n    </ul>\\n\\n    <h2 id=\\"oidc-vs-oauth2\\">OAuth2 vs OIDC (in this story)</h2>\\n    <div class=\\"kv\\">\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">OAuth2</div>\\n        <div>How the client obtains an <strong>access token</strong> to call an API.</div>\\n      </div>\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">OIDC</div>\\n        <div>Adds <strong>authentication</strong> (\u201clogin\u201d) and identity info (ID token + claims) on top of OAuth2.</div>\\n      </div>\\n    </div>\\n    <p>In practice:</p>\\n    <ul>\\n      <li>The React app uses <strong>OIDC</strong> to sign in with an IdP (e.g., Google Workspace).</li>\\n      <li>The React app uses the resulting <strong>access token</strong> as the Bearer token when calling FastAPI.</li>\\n    </ul>\\n\\n    <h2 id=\\"pkce\\">What PKCE is (and why you need it)</h2>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"the-problem-pkce-solves\\">The problem PKCE solves</h3>\\n      <p>\\n        A React SPA is a <strong>public client</strong>: it cannot safely store a permanent client secret in the browser.\\n        Without protection, an attacker who steals the authorization code could exchange it for tokens.\\n      </p>\\n\\n      <h3 id=\\"pkce-in-one-sentence\\">PKCE in one sentence</h3>\\n      <p>\\n        PKCE (\u201cProof Key for Code Exchange\u201d) makes the authorization code usable only by the same client instance that started the login.\\n      </p>\\n\\n      <h3 id=\\"how-pkce-works-simple\\">How PKCE works (simple)</h3>\\n      <ol>\\n        <li>React generates a random secret string: <code>code_verifier</code></li>\\n        <li>React hashes it into <code>code_challenge</code></li>\\n        <li>React sends <code>code_challenge</code> during the login redirect</li>\\n        <li>Later, when exchanging the authorization code for tokens, React must present the original <code>code_verifier</code></li>\\n        <li>The IdP checks the verifier matches the earlier challenge</li>\\n      </ol>\\n\\n      <div class=\\"callout\\">\\n        <strong>Result:</strong> If someone stole the authorization code but doesn\u2019t have the verifier, they can\u2019t get tokens.\\n      </div>\\n\\n      <div class=\\"warn\\">\\n        <strong>Important boundary:</strong> PKCE is between the frontend and the IdP. Your FastAPI backend does not perform PKCE.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"setup\\">What you must set up first (one-time)</h2>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"on-the-identity-provider-e-g-google-identity-workspace\\">On the Identity Provider (e.g., Google Identity / Workspace)</h3>\\n      <ul>\\n        <li>Create an OAuth client for your SPA</li>\\n        <li>You get a <code>client_id</code></li>\\n        <li>Set redirect URI (e.g., <code>https://app.example.com/callback</code>)</li>\\n        <li>Choose scopes (typical: <code>openid email profile</code>)</li>\\n      </ul>\\n\\n      <h3 id=\\"on-fastapi-what-the-backend-keeps\\">On FastAPI (what the backend \u201ckeeps\u201d)</h3>\\n      <p>The backend remains stateless and does not store per-user sessions. It keeps:</p>\\n      <ul>\\n        <li>Trusted issuer(s) (who is allowed to mint tokens)</li>\\n        <li>Expected audience (token must be intended for your API/client)</li>\\n        <li>Access to the IdP\u2019s public signing keys (JWKS), usually cached</li>\\n      </ul>\\n      <div class=\\"callout\\"><strong>That\u2019s enough</strong> to validate tokens for any user on any request.</div>\\n    </div>\\n\\n    <h2 id=\\"sequence\\">Concrete message sequence (OIDC Authorization Code + PKCE)</h2>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"1-react-redirects-user-to-the-idp-authorize-includes-pkce-challenge\\">1) React redirects user to the IdP /authorize (includes PKCE challenge)</h3>\\n      <pre>GET https://accounts.google.com/o/oauth2/v2/auth?\\n  response_type=code&amp;\\n  client_id=YOUR_CLIENT_ID&amp;\\n  redirect_uri=https%3A%2F%2Fapp.example.com%2Fcallback&amp;\\n  scope=openid%20email%20profile&amp;\\n  state=RANDOM_STATE&amp;\\n  code_challenge=PKCE_CHALLENGE&amp;\\n  code_challenge_method=S256</pre>\\n      <ul>\\n        <li><code>response_type=code</code> \u2192 request an authorization code</li>\\n        <li><code>scope=openid ...</code> \u2192 OIDC login + identity</li>\\n        <li><code>code_challenge</code> \u2192 PKCE protection</li>\\n      </ul>\\n\\n      <h3 id=\\"2-idp-redirects-back-with-the-authorization-code\\">2) IdP redirects back with the authorization code</h3>\\n      <pre>GET https://app.example.com/callback?code=AUTH_CODE&amp;state=RANDOM_STATE</pre>\\n\\n      <h3 id=\\"3-react-exchanges-code-for-tokens-at-token-includes-pkce-verifier\\">3) React exchanges code for tokens at /token (includes PKCE verifier)</h3>\\n      <pre>POST https://oauth2.googleapis.com/token HTTP/1.1\\nContent-Type: application/x-www-form-urlencoded\\n\\ngrant_type=authorization_code&amp;\\ncode=AUTH_CODE&amp;\\nredirect_uri=https%3A%2F%2Fapp.example.com%2Fcallback&amp;\\nclient_id=YOUR_CLIENT_ID&amp;\\ncode_verifier=PKCE_VERIFIER</pre>\\n\\n      <h3 id=\\"4-idp-returns-tokens\\">4) IdP returns tokens</h3>\\n      <pre>{\\n  \\"token_type\\": \\"Bearer\\",\\n  \\"access_token\\": \\"....\\",\\n  \\"id_token\\": \\"....\\",\\n  \\"expires_in\\": 3600,\\n  \\"scope\\": \\"openid email profile\\"\\n}</pre>\\n      <p>Now the frontend can call your API.</p>\\n    </div>\\n\\n    <h2 id=\\"the-api-call-to-fastapi-per-user-per-request\\">The API call to FastAPI (per user, per request)</h2>\\n    <pre>POST /query HTTP/1.1\\nHost: api.example.com\\nAuthorization: Bearer &lt;access_token_for_user_742&gt;\\nContent-Type: application/json\\n\\n{ \\"question\\": \\"...\\" }</pre>\\n\\n    <h2 id=\\"backend-validation\\">How the backend knows the token is \u201ccorrect\u201d</h2>\\n    <p>FastAPI doesn\u2019t \u201ctrust the browser\u201d. It trusts the IdP\u2019s signature + standard token checks.</p>\\n\\n    <div class=\\"callout\\">\\n      <strong>Does the backend call the IdP on every request?</strong><br>\\n      Usually <strong>no</strong>. With <strong>JWT access tokens</strong>, the backend verifies the signature locally using the IdP\u2019s\\n      <strong>public keys</strong> (from <strong>JWKS</strong>), plus it checks standard claims (<code>iss</code>, <code>aud</code>, <code>exp</code>).\\n      The backend may fetch JWKS occasionally (and cache it), not per request.\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"what-signature-verification-using-jwks-means\\">What \u201csignature verification using JWKS\u201d means</h3>\\n      <ol>\\n        <li>The IdP signs the JWT with its <strong>private key</strong> when issuing the token.</li>\\n        <li>The backend reads the token header (often containing <code>kid</code>).</li>\\n        <li>The backend selects the matching <strong>public key</strong> from the cached <strong>JWKS</strong>.</li>\\n        <li>The backend verifies the JWT signature. If it matches, the token was minted by the IdP and wasn\u2019t altered.</li>\\n      </ol>\\n    </div>\\n\\n    <div class=\\"card\\" id=\\"jwks-fetch-cache\\">\\n      <h3 id=\\"how-the-backend-gets-jwks-where-it-caches-it-and-when-it-refreshes\\">How the backend gets JWKS, where it caches it, and when it refreshes</h3>\\n      <p>\\n        <strong>Where does JWKS come from?</strong> In OIDC, the IdP exposes a discovery document at\\n        <code>/.well-known/openid-configuration</code>. That JSON includes a <code>jwks_uri</code> URL.\\n      </p>\\n      <p>\\n        <strong>Where is it cached?</strong> Most APIs cache JWKS <strong>in memory</strong> inside each running process (each Uvicorn worker / each GKE pod).\\n        That means:\\n      </p>\\n      <ul>\\n        <li>Pod A caches keys in Pod A memory (Pod B has its own cache).</li>\\n        <li>On restart/rollout, the cache is empty and re-fetched on first request (or warm-up).</li>\\n      </ul>\\n      <p>\\n        <strong>When does it refresh?</strong> Common triggers:\\n      </p>\\n      <ul>\\n        <li><strong>TTL expiry</strong> (e.g., refresh every 5\u201360 minutes).</li>\\n        <li><strong>Unknown <code>kid</code></strong> (IdP rotated keys; refetch JWKS and retry once).</li>\\n        <li><strong>Startup warm-up</strong> (optional: fetch once at boot so first request is fast).</li>\\n      </ul>\\n\\n      <div class=\\"callout\\">\\n        <strong>Practical note:</strong> caching is an optimization; correctness comes from signature verification + claim checks.\\n        Key rotation is why \u201crefetch on unknown kid\u201d is a standard pattern.\\n      </div>\\n\\n    </div>\\n\\n    <h2 id=\\"onboarding\\">From a Verified Identity to Application Access</h2>\\n    <p>\\n      A valid token proves that the configured issuer authenticated a subject;\\n      it does not automatically grant that subject access to your application.\\n      The API still needs a local onboarding and authorization decision.\\n    </p>\\n\\n    <ol>\\n      <li>Validate the token completely before reading identity claims.</li>\\n      <li>Build the stable external key from <code>(iss, sub)</code>, not email or the token string.</li>\\n      <li>Look up or idempotently create the local user in one database transaction.</li>\\n      <li>Require an invitation, approved domain policy, or administrator action before creating tenant membership.</li>\\n      <li>Load current roles and permissions from your application policy store.</li>\\n    </ol>\\n\\n    <div class=\\"warn\\">\\n      <strong>Do not equate email domain with authorization.</strong>\\n      A verified domain can be one onboarding signal, but a user can change\\n      address, leave an organization, or belong to several tenants. Persist an\\n      explicit membership and check its current status on protected requests.\\n    </div>\\n\\n    <h2 id=\\"final-mapping\\">How the Backend Maps a Dynamic Token to a Stable User ID</h2>\\n    <p>The backend does not identify a user by the literal Bearer token string (because tokens change over time). Instead, it uses a 3-step mapping for every single request:</p>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"1-validate-the-bearer-token\\">1) Validate the Bearer token</h3>\\n      <p>The token is usually a JWT signed by your Identity Provider (e.g., Google). FastAPI verifies the signature using the IdP\u2019s public keys (JWKS) and checks basic claims like:</p>\\n      <ul>\\n        <li><code>exp</code> (not expired)</li>\\n        <li><code>iss</code> (issued by the expected IdP)</li>\\n        <li><code>aud</code> (intended for your app/API)</li>\\n      </ul>\\n      <p>If any check fails, the request is rejected (401).</p>\\n\\n      <h3 id=\\"2-extract-a-stable-user-identifier-user-id\\">2) Extract a stable user identifier \u2192 <code>user_id</code></h3>\\n      <p>After validation, FastAPI reads the token\u2019s claims (the payload). The <code>sub</code> (subject) claim is typically the stable unique identifier for the user at that IdP.</p>\\n      <pre>user_id = claims[\\"sub\\"]</pre>\\n\\n      <h3 id=\\"3-derive-or-look-up-the-tenant-tenant-id\\">3) Derive or look up the tenant \u2192 <code>tenant_id</code></h3>\\n      <p>The backend then determines which tenant that user belongs to, using one of these common strategies:</p>\\n      <ul>\\n        <li><strong>Claim-based:</strong> If the token includes a tenant/org claim (e.g. <code>tenant_id</code>, <code>tid</code>, <code>org_id</code>), use it directly.</li>\\n        <li><strong>Database mapping (most common):</strong> Store a user table keyed by <code>(iss, sub)</code>. Look up <code>(claims[\\"iss\\"], claims[\\"sub\\"])</code> to find the <code>tenant_id</code>. If not found, you can optionally provision the user and assign a tenant.</li>\\n        <li><strong>Domain mapping (common for Google Workspace):</strong> Use the <code>email</code> claim and map the domain to a tenant (e.g., <code>alice@acme.com</code> \u2192 tenant \u201cacme\u201d).</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"callout\\">\\n      <strong>Key idea:</strong> Tokens rotate, but <code>sub</code> (plus <code>iss</code>) is stable. The mapping is always:\\n      token \u2192 validated claims \u2192 stable user key \u2192 tenant.\\n    </div>\\n\\n    <div class=\\"warn\\">\\n      <strong>Anti-pattern:</strong> don\u2019t store \u201ccurrent user\u201d in a global variable and don\u2019t treat the token value as a permanent user identifier.\\n      Tokens are short-lived and will naturally differ across time and devices.\\n    </div>\\n\\n    <h2 id=\\"scale\\">Why the Pattern Scales</h2>\\n    <p>\\n      Each API instance can validate a JWT locally with cached public keys, so\\n      token verification does not require a network round trip to the IdP for\\n      every request. Because identity is reconstructed from the request, any\\n      healthy FastAPI worker can handle the next call; no sticky session or\\n      process-global \u201ccurrent user\u201d is required.\\n    </p>\\n\\n    <table>\\n      <thead><tr><th>Layer</th><th>Scale mechanism</th><th>Correctness requirement</th></tr></thead>\\n      <tbody>\\n        <tr><td>JWT verification</td><td>Per-process JWKS cache</td><td>Issuer, audience, time, signature, and algorithm checks on every request</td></tr>\\n        <tr><td>User mapping</td><td>Indexed lookup on <code>(iss, sub)</code></td><td>Unique constraint and idempotent provisioning</td></tr>\\n        <tr><td>Tenant authorization</td><td>Short-lived policy cache where justified</td><td>Tenant membership remains explicit and revocable</td></tr>\\n        <tr><td>API compute</td><td>Stateless horizontal replicas</td><td>Request-scoped identity and no mutable global user state</td></tr>\\n      </tbody>\\n    </table>\\n\\n    <p>\\n      Local JWT validation trades immediate token revocation for low-latency\\n      verification. Keep access tokens short-lived, revoke sessions or refresh\\n      tokens at the authorization server, and re-check high-risk application\\n      permissions at the point of action.\\n    </p>\\n  </div>"}'),c={title:"OIDC + OAuth2 + PKCE \u2192 Bearer Token \u2192 FastAPI Identity",slug:"/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi",description:"This is the same story end-to-end: how a React SPA securely obtains an access_token (PKCE), and how FastAPI validates that token and maps it to tenant_id + user_id per request.",sidebar_label:"8. OIDC, OAuth 2.0, and PKCE in FastAPI",pagination_label:"8. OIDC, OAuth 2.0, and PKCE in FastAPI",hide_title:!0,hide_table_of_contents:!0},d=void 0,l={},h=[];function p(e){return(0,i.jsx)(s.A,{content:r})}function u(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(p,{...e})}):p()}}}]);